class _UniffiConverterBool:
    @classmethod
    def check_lower(cls, value):
        return not not value

    @classmethod
    def lower(cls, value):
        return 1 if value else 0

    @staticmethod
    def lift(value):
        return value != 0

    @classmethod
    def read(cls, buf):
        return cls.lift(buf.read_u8())

    @classmethod
    def write(cls, value, buf):
        buf.write_u8(value)

class _UniffiConverterString:
    @staticmethod
    def check_lower(value):
        if not isinstance(value, str):
            raise TypeError("argument must be str, not {}".format(type(value).__name__))
        return value

    @staticmethod
    def read(buf):
        size = buf.read_i32()
        if size < 0:
            raise InternalError("Unexpected negative string length")
        utf8_bytes = buf.read(size)
        return utf8_bytes.decode("utf-8")

    @staticmethod
    def write(value, buf):
        utf8_bytes = value.encode("utf-8")
        buf.write_i32(len(utf8_bytes))
        buf.write(utf8_bytes)

    @staticmethod
    def lift(buf):
        with buf.consume_with_stream() as stream:
            return stream.read(stream.remaining()).decode("utf-8")

    @staticmethod
    def lower(value):
        with _UniffiRustBuffer.alloc_with_builder() as builder:
            builder.write(value.encode("utf-8"))
            return builder.finalize()

class _UniffiConverterBytes(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        size = buf.read_i32()
        if size < 0:
            raise InternalError("Unexpected negative byte string length")
        return buf.read(size)

    @staticmethod
    def check_lower(value):
        try:
            memoryview(value)
        except TypeError:
            raise TypeError("a bytes-like object is required, not {!r}".format(type(value).__name__))

    @staticmethod
    def write(value, buf):
        buf.write_i32(len(value))
        buf.write(value)






class AccountAddresses:
    """
    Grouped address lists for an account.
    """

    used: "typing.List[AddressInfo]"
    """
    Used receive addresses (have at least one transaction)
    """

    unused: "typing.List[AddressInfo]"
    """
    Unused receive addresses (no transactions yet)
    """

    change: "typing.List[AddressInfo]"
    """
    Change addresses
    """

    def __init__(self, *, used: "typing.List[AddressInfo]", unused: "typing.List[AddressInfo]", change: "typing.List[AddressInfo]"):
        self.used = used
        self.unused = unused
        self.change = change

    def __str__(self):
        return "AccountAddresses(used={}, unused={}, change={})".format(self.used, self.unused, self.change)

    def __eq__(self, other):
        if self.used != other.used:
            return False
        if self.unused != other.unused:
            return False
        if self.change != other.change:
            return False
        return True

class _UniffiConverterTypeAccountAddresses(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        return AccountAddresses(
            used=_UniffiConverterSequenceTypeAddressInfo.read(buf),
            unused=_UniffiConverterSequenceTypeAddressInfo.read(buf),
            change=_UniffiConverterSequenceTypeAddressInfo.read(buf),
        )

    @staticmethod
    def check_lower(value):
        _UniffiConverterSequenceTypeAddressInfo.check_lower(value.used)
        _UniffiConverterSequenceTypeAddressInfo.check_lower(value.unused)
        _UniffiConverterSequenceTypeAddressInfo.check_lower(value.change)

    @staticmethod
    def write(value, buf):
        _UniffiConverterSequenceTypeAddressInfo.write(value.used, buf)
        _UniffiConverterSequenceTypeAddressInfo.write(value.unused, buf)
        _UniffiConverterSequenceTypeAddressInfo.write(value.change, buf)


class AccountInfoResult:
    """
    Result from querying an extended public key via Electrum.
    """

    account: "ComposeAccount"
    """
    The account structure with addresses and UTXOs
    """

    balance: "int"
    """
    Total confirmed balance in satoshis
    """

    utxo_count: "int"
    """
    Number of UTXOs
    """

    account_type: "AccountType"
    """
    The detected or specified account type
    """

    block_height: "int"
    """
    The current blockchain tip height
    """

    def __init__(self, *, account: "ComposeAccount", balance: "int", utxo_count: "int", account_type: "AccountType", block_height: "int"):
        self.account = account
        self.balance = balance
        self.utxo_count = utxo_count
        self.account_type = account_type
        self.block_height = block_height

    def __str__(self):
        return "AccountInfoResult(account={}, balance={}, utxo_count={}, account_type={}, block_height={})".format(self.account, self.balance, self.utxo_count, self.account_type, self.block_height)

    def __eq__(self, other):
        if self.account != other.account:
            return False
        if self.balance != other.balance:
            return False
        if self.utxo_count != other.utxo_count:
            return False
        if self.account_type != other.account_type:
            return False
        if self.block_height != other.block_height:
            return False
        return True

